triples = [("mars","is-a","planet"),("mars","color","red"),("venus","is-a","planet")]
def match(pat):
    return [{("s","p","o")[i]: v for i, v in enumerate(t) if pat[i]=="?"}
            for t in triples if all(p=="?" or p==v for p, v in zip(pat, t))]
res = match(("?", "is-a", "planet"))
print("planets:", [r["s"] for r in res])
assert {r["s"] for r in res} == {"mars", "venus"}

aliases = {}
def merge(canonical, variant, src):
    aliases.setdefault(canonical, {"names": set(), "srcs": set()})
    aliases[canonical]["names"].add(variant); aliases[canonical]["srcs"].add(src)
merge("mars", "Mars", "archive-a"); merge("mars", "MARS", "archive-b")
print(aliases["mars"])
assert aliases["mars"]["srcs"] == {"archive-a", "archive-b"}

shapes = {"planet": {"required": ["orbital-period"]}}
nodes = {"mars": {"class": "planet", "orbital-period": 687}, "x": {"class": "planet"}}
bad = [n for n, a in nodes.items()
       if any(r not in a for r in shapes[a["class"]]["required"])]
print("violations:", bad)
assert bad == ["x"]

